/** Parallax background system for scrolling layers at different depths. */

import { Mesh, MeshBuilder, StandardMaterial, Texture } from "@babylonjs/core";
import type { BabylonHandles } from "../adapters/babylonScene.ts";
import type { Possession } from "../framework/mode.ts";
import type { Resources } from "../kernel/resources.ts";
import type { GameSystem } from "../kernel/systems.ts";
import type { World } from "../kernel/world.ts";

export type ParallaxLayer = {
  texture: string;
  depth: number;
  y?: number;
  scale?: number;
  repeatX?: boolean;
  tint?: string;
};

type LayerState = {
  mesh: Mesh;
  material: StandardMaterial;
  tex: Texture;
  depth: number;
  repeatX: boolean;
  baseU: number;
};

const layerStates: LayerState[] = [];

export function createParallaxSystem(
  world: World,
  handles: BabylonHandles,
  resources: Resources,
  possession: Possession,
): GameSystem {
  return {
    name: "parallax",
    order: 5,
    async init() {
      const layers = resources.manifest.parallaxLayers ?? [];
      if (layers.length === 0) return;

      // Sort by depth (furthest first)
      const sorted = [...layers].sort((a, b) => a.depth - b.depth);

      for (let i = 0; i < sorted.length; i++) {
        const layer = sorted[i];
        await createLayer(handles, layer, i);
      }
    },
    update(ctx) {
      if (layerStates.length === 0) return;

      // Get camera X position for parallax offset
      const pawnId = possession.pawnId;
      const cameraX = pawnId ? world.worldPosition(pawnId).x : 0;

      for (const state of layerStates) {
        // Parallax scroll: lower depth = slower movement
        const scrollSpeed = state.depth * 0.02;

        if (state.repeatX) {
          // Negative offset - when walking right, background scrolls right (slower than player)
          state.tex.uOffset = state.baseU - cameraX * scrollSpeed;
        }
        
        // Keep parallax centered on camera X
        state.mesh.position.x = cameraX;
      }
    },
  };
}

async function createLayer(
  handles: BabylonHandles,
  layer: ParallaxLayer,
  index: number,
): Promise<void> {
  const scale = layer.scale ?? 1;
  const width = 200 * scale; // Wider to prevent cut-off
  const height = 50 * scale; // Taller for better coverage
  const y = layer.y ?? 5;
  // Position between camera (z~20) and game world (z=0)
  // Further layers (lower depth) are closer to game world
  const z = 10 - index * 2;

  // Create plane mesh
  const mesh = MeshBuilder.CreatePlane(
    `parallax_${index}`,
    { width, height, sideOrientation: Mesh.DOUBLESIDE },
    handles.scene,
  );
  mesh.position.set(0, y, z);
  mesh.rotation.y = Math.PI; // Face toward camera (which is at +Z)
  mesh.renderingGroupId = 0; // Render before game content (sprites use group 1)
  mesh.isPickable = false;

  // Create material
  const material = new StandardMaterial(`parallax_mat_${index}`, handles.scene);
  material.backFaceCulling = false;
  material.disableLighting = true;
  material.emissiveColor.set(1, 1, 1);

  // Apply tint if specified
  if (layer.tint) {
    const hex = layer.tint.replace("#", "");
    const r = parseInt(hex.substring(0, 2), 16) / 255;
    const g = parseInt(hex.substring(2, 4), 16) / 255;
    const b = parseInt(hex.substring(4, 6), 16) / 255;
    material.emissiveColor.set(r, g, b);
  }

  // Load texture
  const texPath = layer.texture.startsWith("/") ? layer.texture : `/assets/${layer.texture}`;
  const tex = new Texture(texPath, handles.scene, false, true, Texture.BILINEAR_SAMPLINGMODE);
  tex.hasAlpha = true;

  if (layer.repeatX) {
    tex.wrapU = Texture.WRAP_ADDRESSMODE;
    tex.uScale = width / (height * 2); // Tile based on aspect ratio
  } else {
    tex.wrapU = Texture.CLAMP_ADDRESSMODE;
  }
  tex.wrapV = Texture.CLAMP_ADDRESSMODE;

  material.diffuseTexture = tex;
  material.useAlphaFromDiffuseTexture = true;
  material.transparencyMode = 2; // ALPHA_TEST

  mesh.material = material;

  layerStates.push({
    mesh,
    material,
    tex,
    depth: layer.depth,
    repeatX: layer.repeatX ?? false,
    baseU: 0,
  });
}

/** Clean up parallax layers. */
export function disposeParallax(): void {
  for (const state of layerStates) {
    state.mesh.dispose();
    state.material.dispose();
    state.tex.dispose();
  }
  layerStates.length = 0;
}
